mapper.select:
SELECT apr90_disposal_list_id AS disposal_list_id , apr90_appr_id AS appr_id , apr90_disposal_cd AS disposal_code , f_cdnm('DisposalCode', apr90_disposal_cd, apr90_company_id, apr90_reg_date) AS disposal_name , apr90_reg_date AS reg_date , f_emp_kor_nm(apr90_reg_emp_id) AS reg_emp_name , appr.title AS title , f_cdnm('AprStatusCode', appr.status_cd, apr90_company_id, appr.reg_date) AS status_name , apr90_reason AS reason , apr90_confirm_yn AS confirm_yn , f_emp_kor_nm(apr90_confirm_emp_id) AS confirm_emp_name , apr90_confirm_date AS confirm_date FROM apr90_disposal_list LEFT OUTER JOIN ( SELECT apr01_appr_id AS appr_id , apr01_title AS title , apr01_status_cd AS status_cd , apr01_reg_date AS reg_date FROM apr01_appr WHERE 1=1 UNION ALL SELECT apr99_appr_id AS appr_id , apr99_title AS title , apr99_status_cd AS status_cd , apr99_reg_date AS reg_date FROM apr99_appr_del WHERE 1=1 ) appr ON appr.appr_id = apr90_appr_id WHERE 1=1 AND apr90_company_id = #{c.companyId} AND apr90_disposal_cd LIKE #{c.disposalCode} AND apr90_reg_date BETWEEN #{c.startDate} AND #{c.closeDate}
AND apr90_confirm_emp_id = #{c.confirmEmpId}
ORDER BY apr90_reg_date , appr.title DESC

SELECT apr90_appr_id
  FROM apr90_disposal_list
 WHERE apr90_disposal_list_id = #{disposalListId}
   AND apr90_company_id = #{companyId}

mapper.update:
UPDATE apr90_disposal_list
   SET apr90_disposal_cd     = #{disposalCode}
     , apr90_confirm_emp_id  = #{confirmEmpId}
     , apr90_confirm_date    = #{confirmDate}
     , apr90_confirm_yn      = #{confirmYn}
 WHERE apr90_disposal_list_id = #{disposalListId}

UPDATE opr01_create
   SET opr01_appr_id = NULL
 WHERE opr01_appr_id = #{apprId}

UPDATE pln02_plan
   SET pln02_appr_id = NULL
 WHERE pln02_appr_id = #{apprId}
